import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 _unlockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        assertTrue(!reverted && afterBalance == beforeBalance + amount);
    }

    function testFuzz_run(uint256 _unlockTime, uint256 amount) public {
        _run(_unlockTime, amount);
    }

    receive() external payable {}
}

