contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am, uint _putAmount) public payable {
        require(_putAmount >= 1 ether);
        require(address(this).balance >= _putAmount);

        c.Put{value: _putAmount}(0);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        require(beforeBal >= 1 ether);

        bool reverted;
        uint balBefore = address(c).balance;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        if (!reverted) {
            uint expected = _am <= beforeBal ? _am : beforeBal;
            assert(afterBal == beforeBal - expected);
            assert(balBefore - address(c).balance == expected);
        } else {
            assert(afterBal == beforeBal);
            assert(address(c).balance == balBefore);
        }
    }

    receive() external payable {}
}

